 return `<aside class="profile-card"><div class="avatar" id="avatar"><span class="initials">RS</span><img src="assets/profile.png" alt="P Revanth Sai"></div><h3>P Revanth Sai</h3><p>Java Programming · II Year AI&ML</p><div class="meta">
 <div><small>Roll No.</small><b>25EU02112</b></div><div><small>Section</small><b>Section 2</b></div>
 <div><small>Year</small><b>II Year</b></div><div><small>Branch</small><b>AI&ML</b></div></div></aside>`;
