function home(){
 const cards=Object.entries(weeks).map(([n,v])=>`<a class="week-card" href="#week/${n}"><span class="week-no">WEEK ${n}</span><h3>${v[0]}</h3><p>${v[1]}</p><span class="arrow">↗</span></a>`).join("");
 return layout(`<section class="hero"><div><div class="eyebrow">Java Programming · Practice Collection</div><h1>Explore.<br><span>Task brief.</span><br>Improve.</h1><p>A personal collection of Java lab work, grouped into modules from introductory syntax to file operations, concurrency, and functional techniques.</p></div>${profileCard()}</section>
 <section class="section" id="weeks"><div class="section-head"><div><div class="eyebrow">Course Map</div><h2>Pick a lab block</h2></div><p>Open a module to review its task brief, source listing, and sample console response in one place.</p></div><div class="week-grid">${cards}</div></section>
 <section class="section profile-section" id="profile"><div class="panel"><div class="eyebrow">Collection notes</div><h2>A workspace for Java exercises.</h2><p>This site brings the course exercises together in a navigable format, making each task easier to revisit, present, and practise independently.</p></div><div class="panel"><div class="eyebrow">About the learner</div><div class="info-list">
 <div class="info"><small>Name</small>P Revanth Sai</div><div class="info"><small>Roll Number</small>25EU02112</div><div class="info"><small>Year</small>II Year</div><div class="info"><small>Branch</small>AI&ML</div><div class="info"><small>Section</small>Section 2</div><div class="info"><small>Subject</small>Java Programming</div>
 </div></div></section>`);
}
function weekPage(n){
 const meta=weeks[n], list=n==2?week2:byWeek(n);
 if(n==1) return layout(`<div class="breadcrumb">Home / Module 1</div><section class="week-hero"><div><div class="eyebrow">Module 01</div><h1>${meta[0]}</h1><p>${meta[1]}</p></div></section><div class="block"><h2>Language comparison</h2><div class="table-wrap"><table class="compare"><thead><tr><th>Language</th><th>Paradigm</th><th>How it runs</th><th>Memory handling</th><th>Typical applications</th></tr></thead><tbody>${week1Rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`);
 if(n===4||n===5) return layout(`<div class="breadcrumb">Home / Module ${n}</div><section class="week-hero"><div><div class="eyebrow">Module ${String(n).padStart(2,"0")}</div><h1>${meta[0]}</h1><p>${meta[1]}</p></div></section><div class="empty">There are no coding exercises listed for this module.</div>`);
 return layout(`<div class="breadcrumb">Home / Module ${n}</div><section class="week-hero"><div><div class="eyebrow">Module ${String(n).padStart(2,"0")}</div><h1>${meta[0]}</h1><p>${meta[1]}</p></div></section><div class="program-list">${list.map(p=>`<a class="program-card" href="#week/${n}/program/${p.no}"><span class="num">TASK ${String(p.no).padStart(2,"0")}</span><h3>${p.title}</h3><p>${p.question}</p></a>`).join("")}</div>`);
}
function detail(n,pno){
 const list=n==2?week2:byWeek(n), p=list.find(x=>x.no==pno); if(!p)return home();
 return layout(`<div class="detail"><a class="back" href="#week/${n}">← Return to module ${n}</a><div class="detail-head"><div><div class="eyebrow">Module ${n} · Program ${String(pno).padStart(2,"0")}</div><h1>${p.title}</h1></div></div>
 <div class="block"><h2>Task brief</h2><div class="question">${p.question}</div></div>
 <div class="block"><h2>Code listing</h2><div class="code-wrap"><button class="copy" onclick="copyCode()">Copy listing</button><pre id="code">${esc(p.code)}</pre></div></div>
 <div class="block"><h2>Console preview</h2><div class="output">${esc(p.output)}</div></div></div>`);
}
window.copyCode=()=>navigator.clipboard.writeText(document.getElementById("code").innerText).then(()=>{document.querySelector(".copy").textContent="Copied";setTimeout(()=>document.querySelector(".copy").textContent="Copy listing",1000)});
function route(){
 const parts=location.hash.replace("#","").split("/").filter(Boolean);
 let html;
 if(!parts.length||parts[0]==="home")html=home();
 else if(parts[0]==="week"&&parts[2]==="program")html=detail(Number(parts[1]),Number(parts[3]));
 else if(parts[0]==="week")html=weekPage(Number(parts[1]));
 else html=home();
 app.innerHTML=html;activateAvatar();window.scrollTo(0,0);
}
document.getElementById("themeBtn").onclick=()=>document.body.classList.toggle("dark");
window.addEventListener("hashchange",route);route();